using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;
[InitializeOnLoad]public static class DockSideRopeUV{static DockSideRopeUV(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("DockSideRopeUV.request"))return;File.Delete("DockSideRopeUV.request");try{int ropes=0,sides=0;var seen=new HashSet<Mesh>();foreach(string path in Enumerable.Range(1,6).Select(i=>"Assets/Scenes/Oasis/SouthBeach/Docking Pier "+i+".prefab").Concat(new[]{"Assets/Scenes/Oasis/YachtPortAtlas/Yatch Port Edge Details.prefab"})){var prefab=PrefabUtility.LoadPrefabContents(path);foreach(var f in prefab.GetComponentsInChildren<MeshFilter>()){var mesh=f.sharedMesh;if(!seen.Add(mesh))continue;var p=mesh.vertices;var normals=mesh.normals;var uv=mesh.uv;var flags=new List<Vector4>();mesh.GetUVs(1,flags);var ids=mesh.triangles;for(int k=0;k<ids.Length;k+=3){int a=ids[k],b=ids[k+1],c=ids[k+2];bool rope=flags[a].x==3;bool edge=f.name.Contains("deck and foundation")&&flags[a].x==0&&Mathf.Abs(normals[a].y)<.65f;if(!rope&&!edge)continue;Vector3 axis;if(rope){var candidates=new[]{p[b]-p[a],p[c]-p[a],p[c]-p[b]};axis=candidates.OrderByDescending(v=>v.sqrMagnitude).First().normalized;if(axis.x+axis.z<0)axis=-axis;}else axis=Mathf.Abs(normals[a].x)>.5f?Vector3.forward:Vector3.right;foreach(int j in new[]{a,b,c}){uv[j]=new Vector2(Vector3.Dot(p[j],axis)*(rope?2f:.5f),p[j].y*.3f);flags[j]=new Vector4(rope?3:0,flags[j].y,rope?0:1,0);}if(rope)ropes++;else sides++;}mesh.uv=uv;mesh.SetUVs(1,flags);EditorUtility.SetDirty(mesh);}PrefabUtility.UnloadPrefabContents(prefab);}AssetDatabase.SaveAssets();File.WriteAllText("FinalEnvironmentRoadReview/DockSideRopeUVReport.txt","SUCCESS rope faces="+ropes+" deck side faces="+sides+"; rope tile3 longitudinal mapping; deck fascia continuous single wood-board grain aligned to local side direction; one atlas/material retained.");}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/DockSideRopeUVReport.txt","FAILED "+e);Debug.LogException(e);}}}
